.ledger--plain .ledger-row{grid-template-columns:1fr;}
.ledger--plain .ledger-body p{max-width:60ch;}
.ledger--plain .ledger-body h3{font-size:1.15rem;}

/* PLAN 045 (R11, loop 5): processakten inverterad, ett läge av samma
   sida (?process=invert), inte en andra sida. Additivt block, ingen
   befintlig rad ovan rörd. Fyra tokens vänder hela aktens ritregister
   (.contour/.dimline/.guide/.leader läser --ink/--hair-ink,
   .measure läser --c-accent, .ledger/.ledger-row läser
   --c-line-on-paper, .process/.principles sätter bg/color ur --bg/
   --ink) - se planens eget "Varför tokens och inte en omskrivning
   per regel". --hair-ink substituerar vid DEKLARATIONSTILLFÄLLET
   (color-mix(in srgb, var(--ink) 62%, var(--bg)), rad 156) och ärver
   därför INTE de omskrivna --ink/--bg härifrån; skriven om separat. */
:root[data-process="invert"] #process,
:root[data-process="invert"] .principles{
  --bg: var(--c-black);
  --ink: var(--c-paper);
  --c-line-on-paper: var(--hairline-dark);
  --c-accent: var(--c-accent-on-dark);
  --hair-ink: color-mix(in srgb, var(--c-paper) 62%, var(--c-black));
}
/* De fyra hårdkodade bläcktonerna (rgba(), ingen token) blir nära
   svarta mot mörkt om de lämnas - de enda undantagen från tokenvägen. */
:root[data-process="invert"] #process .process-lead,
:root[data-process="invert"] #process .process-p,
:root[data-process="invert"] .principles .ledger-body p{
  color: color-mix(in srgb, var(--c-paper) 78%, var(--c-black));
}
:root[data-process="invert"] .principles .ledger-num{
  color: color-mix(in srgb, var(--c-paper) 62%, var(--c-black));
}

