"""045 grind A.1: render identity for paper mode (no ?process= in URL). Dumps
color/background-color/fill/stroke for the listed selectors, JSON to stdout+file."""
import json, sys
from playwright.sync_api import sync_playwright
URL = "http://localhost:3301/tests/alunix-r8/runs/V3c/index.html"
CHROME = "C:/Program Files/Google/Chrome/Application/chrome.exe"
SELECTORS = [".process", ".process-title", ".process-lead", ".process-p", ".process-note",
             ".ledger-body p", ".ledger-num", ".giant-sub", ".measure", ".contour",
             ".dimline", ".principles"]
JS = """(sels) => {
  const out = {};
  for (const s of sels) {
    const el = document.querySelector(s);
    if (!el) { out[s] = null; continue; }
    const cs = getComputedStyle(el);
    out[s] = {color: cs.color, backgroundColor: cs.backgroundColor, fill: cs.fill, stroke: cs.stroke};
  }
  return out;
}"""
with sync_playwright() as pw:
    b = pw.chromium.launch(executable_path=CHROME)
    page = b.new_page(viewport={"width":1440,"height":900}, reduced_motion="reduce")
    page.goto(URL, wait_until="load")
    page.wait_for_timeout(1500)
    # scroll into the process/principles act so getComputedStyle reflects real rendered state
    page.evaluate("window.scrollTo(0, 5400)")
    page.wait_for_timeout(1000)
    result = page.evaluate(JS, SELECTORS)
    b.close()
print(json.dumps(result, indent=1))
json.dump(result, open(sys.argv[1] if len(sys.argv) > 1 else "render_identity.json", "w"), indent=1)

